// Offline↔browser parity, in CI. jax-js (Node, wasm/cpu backend) running the
// REAL model.ts forward/backward must match a golden fixture generated by the
// finite-difference-validated PyTorch reference (spikes/m0/parity/ref.py math,
// tiny config, via gen_ci_fixture.py). If model.ts ever drifts from the offline
// trainer's numerics — the thing that lets flagship/time-machine checkpoints
// load and run correctly — this test fails. No GPU needed; runs in the normal
// unit suite. Tolerance matches the M0 gate (compare.mjs): max-rel ≤ 1e-3
// (WebGPU/wasm float reduction order differs from torch; M0 worst was 3.7e-4).
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { init, defaultDevice, numpy as np, nn, valueAndGrad, tree } from '@jax-js/jax';
import { forwardLogprobs, lossFn } from './model';
import type { ModelConfig } from './engine';

/* eslint-disable @typescript-eslint/no-explicit-any */

interface Golden {
	config: {
		nLayer: number;
		nEmbd: number;
		nHead: number;
		blockSize: number;
		vocab: number;
		batch: number;
	};
	weights: Record<string, number[]>;
	inputIds: number[];
	targetIds: number[];
	logprobs: number[];
	loss: number;
	grads: Record<string, number[]>;
}

const golden = JSON.parse(
	readFileSync(new URL('./fixtures/parity-golden.json', import.meta.url), 'utf8')
) as Golden;

const REL = 1e-3;

function maxRel(actual: ArrayLike<number>, expected: number[]): number {
	let maxAbsRef = 0;
	for (const v of expected) maxAbsRef = Math.max(maxAbsRef, Math.abs(v));
	const floor = Math.max(1e-3 * maxAbsRef, 1e-12); // tiny elements judged on tensor scale
	let mr = 0;
	for (let i = 0; i < expected.length; i++) {
		const d = Math.abs(actual[i] - expected[i]);
		mr = Math.max(mr, d / Math.max(Math.abs(expected[i]), floor));
	}
	return mr;
}

describe('offline↔browser parity (model.ts vs finite-diff-validated torch golden)', () => {
	it('logprobs, loss and every grad agree within 1e-3 rel (jax-js wasm/cpu)', async () => {
		const devices = await init();
		defaultDevice(devices.includes('wasm') ? 'wasm' : 'cpu');

		const c = golden.config;
		const { vocab: V, nEmbd: D, blockSize: S, nLayer: L, batch: B } = c;
		const cfg: ModelConfig = {
			bird: 'quill',
			nLayer: L,
			nEmbd: D,
			nHead: c.nHead,
			blockSize: S,
			vocab: V
		};

		const tensor = (name: string, shape: number[]) =>
			np.array(Float32Array.from(golden.weights[name])).reshape(shape);
		const params: any = {
			wte: tensor('wte', [V, D]),
			wpe: tensor('wpe', [S, D]),
			lmHead: tensor('lmHead', [D, V]),
			layers: Array.from({ length: L }, (_, i) => ({
				wq: tensor(`layers.${i}.wq`, [D, D]),
				wk: tensor(`layers.${i}.wk`, [D, D]),
				wv: tensor(`layers.${i}.wv`, [D, D]),
				wo: tensor(`layers.${i}.wo`, [D, D]),
				mlpFc1: tensor(`layers.${i}.mlpFc1`, [D, 4 * D]),
				mlpFc2: tensor(`layers.${i}.mlpFc2`, [4 * D, D])
			}))
		};

		const inputIds = np
			.array(Int32Array.from(golden.inputIds), { dtype: np.int32 })
			.reshape([B, S]);
		const posIds = np.tile(np.arange(S).astype(np.int32), [B, 1]);
		const targetIds = np
			.array(Int32Array.from(golden.targetIds), { dtype: np.int32 })
			.reshape([B, S]);
		const tokenOH = nn.oneHot(inputIds, V);
		const posOH = nn.oneHot(posIds, S);
		const targetOH = nn.oneHot(targetIds, V);

		// pass 1 — forward log-probs (model.ts consumes the refs it's handed)
		const logprobs = forwardLogprobs(tree.ref(params), cfg, S, tokenOH.ref, posOH.ref);
		const lpData = await logprobs.data();
		const lpRel = maxRel(lpData, golden.logprobs);

		// pass 2 — loss + grads through the real training path
		const [lossVal, grads] = valueAndGrad((p: any) =>
			lossFn(p, cfg, tokenOH.ref, posOH.ref, targetOH.ref)
		)(tree.ref(params));
		const loss = lossVal.item();

		const gradRels: Record<string, number> = {};
		gradRels.wte = maxRel(await grads.wte.data(), golden.grads.wte);
		gradRels.wpe = maxRel(await grads.wpe.data(), golden.grads.wpe);
		gradRels.lmHead = maxRel(await grads.lmHead.data(), golden.grads.lmHead);
		for (let i = 0; i < L; i++) {
			for (const n of ['wq', 'wk', 'wv', 'wo', 'mlpFc1', 'mlpFc2'] as const) {
				gradRels[`layers.${i}.${n}`] = maxRel(
					await grads.layers[i][n].data(),
					golden.grads[`layers.${i}.${n}`]
				);
			}
		}

		// cleanup — the OH/params masters survive (passes consumed .ref copies);
		// logprobs/lossVal/grad leaves were already consumed by .data()/.item().
		tokenOH.dispose();
		posOH.dispose();
		targetOH.dispose();
		for (const l of tree.leaves(params)) l.dispose();

		const lossRel = Math.abs(loss - golden.loss) / Math.abs(golden.loss);
		const worstGrad = Math.max(...Object.values(gradRels));

		console.log(
			`[parity] logprobs ${lpRel.toExponential(2)}  loss ${lossRel.toExponential(2)}  worst-grad ${worstGrad.toExponential(2)} (${Object.entries(gradRels).sort((a, b) => b[1] - a[1])[0][0]})`
		);
		expect(lpRel, `logprobs max-rel ${lpRel.toExponential(2)}`).toBeLessThan(REL);
		expect(lossRel, `loss rel ${lossRel.toExponential(2)}`).toBeLessThan(REL);
		expect(worstGrad, `worst grad max-rel ${worstGrad.toExponential(2)}`).toBeLessThan(REL);
	}, 30000);
});
